#!/usr/bin/env python3
import gzip
import math
import subprocess
import sys

vcf_path, out_path = sys.argv[1], sys.argv[2]
gnomad_url = "https://gnomad-public-us-east-1.s3.amazonaws.com/release/2.1.1/vcf/genomes/gnomad.genomes.r2.1.1.sites.1.vcf.bgz"

pop_fields = {
    "AFR": "AF_afr",
    "ASJ": "AF_asj",
    "EUR": "AF_nfe",
    "EAS": "AF_eas",
    "SAS": "AF_sas",
}

def open_text(path):
    with open(path, "rb") as probe:
        gz = probe.read(2) == b"\x1f\x8b"
    return gzip.open(path, "rt", encoding="utf-8", errors="replace") if gz else open(path, "rt", encoding="utf-8", errors="replace")

def parse_info(info):
    out = {}
    for item in info.split(";"):
        if "=" in item:
            key, val = item.split("=", 1)
            out[key] = val
    return out

samples = []
query = {}
with open_text(vcf_path) as handle, open("regions.tsv", "w", encoding="utf-8") as regions:
    for line in handle:
        if line.startswith("#CHROM"):
            samples = line.rstrip("\n").split("\t")[9:]
            continue
        if line.startswith("#"):
            continue
        fields = line.rstrip("\n").split("\t")
        if len(fields) < 10:
            continue
        chrom, pos_s, _id, ref, alt = fields[:5]
        alts = alt.split(",")
        if chrom != "1" or len(ref) != 1 or not all(len(a) == 1 for a in alts):
            continue
        pos = int(pos_s)
        if pos in query:
            continue
        alt_counts = []
        usable = True
        for sample_field in fields[9:13]:
            gt = sample_field.split(":", 1)[0].replace("|", "/")
            alleles = gt.split("/")
            if len(alleles) != 2 or "." in alleles:
                usable = False
                break
            alt_counts.append(sum(1 for allele in alleles if allele != "0"))
        if usable and len(alt_counts) == 4:
            query[pos] = {"ref": ref, "alts": alts, "alt_counts": alt_counts}
            regions.write(f"1\t{pos}\t{pos}\n")

cmd = ["bcftools", "view", "-R", "regions.tsv", "-H", gnomad_url]
proc = subprocess.run(cmd, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
if proc.returncode != 0:
    with open(out_path, "w", encoding="utf-8") as out:
        out.write("status\terror\n")
        out.write("bcftools_failed\t" + proc.stderr.replace("\n", " ")[:4000] + "\n")
    sys.exit(0)

raw_ll = [{pop: 0.0 for pop in pop_fields} for _ in range(4)]
cond_ll = [{pop: 0.0 for pop in pop_fields} for _ in range(4)]
counts = {pop: 0 for pop in pop_fields}
used_by_sample = [0, 0, 0, 0]
exact_records = 0
position_records = 0

for line in proc.stdout.splitlines():
    fields = line.split("\t")
    if len(fields) < 8:
        continue
    pos = int(fields[1])
    if pos not in query:
        continue
    position_records += 1
    q = query[pos]
    if q["ref"] != fields[3]:
        continue
    g_alts = fields[4].split(",")
    alt_index = None
    for i, alt in enumerate(g_alts):
        if alt in q["alts"]:
            alt_index = i
            break
    if alt_index is None:
        continue
    info = parse_info(fields[7])
    pop_p = {}
    for pop, af_key in pop_fields.items():
        vals = info.get(af_key)
        if vals is None:
            continue
        parts = vals.split(",")
        if alt_index >= len(parts) or parts[alt_index] == ".":
            continue
        try:
            p = float(parts[alt_index])
        except ValueError:
            continue
        p = min(0.999, max(0.001, p))
        pop_p[pop] = p
    if len(pop_p) != len(pop_fields):
        continue
    exact_records += 1
    for pop in pop_p:
        counts[pop] += 1
    for s, ac in enumerate(q["alt_counts"]):
        if ac == 0:
            continue
        used_by_sample[s] += 1
        for pop, p in pop_p.items():
            p0 = (1 - p) * (1 - p)
            p1 = 2 * p * (1 - p)
            p2 = p * p
            gp = p1 if ac == 1 else p2
            raw_ll[s][pop] += math.log(max(gp, 1e-12))
            denom = max(1 - p0, 1e-12)
            cond_ll[s][pop] += math.log(max(gp / denom, 1e-12))

with open(out_path, "w", encoding="utf-8") as out:
    out.write("section\tkey\tvalue\n")
    out.write(f"summary\tquery_snvs\t{len(query)}\n")
    out.write(f"summary\tgnomad_position_records\t{position_records}\n")
    out.write(f"summary\texact_ref_alt_records_with_all_pop_af\t{exact_records}\n")
    out.write(f"summary\tsamples\t{','.join(samples[:4]) if samples else 'Sample1,Sample2,Sample3,Sample4'}\n")
    out.write("summary\tused_by_sample\t" + ",".join(map(str, used_by_sample)) + "\n")
    for s in range(4):
        ranked_cond = sorted(cond_ll[s].items(), key=lambda kv: kv[1], reverse=True)
        ranked_raw = sorted(raw_ll[s].items(), key=lambda kv: kv[1], reverse=True)
        out.write(f"prediction_conditional\tSample{s+1}\t{ranked_cond[0][0]}\n")
        out.write(f"prediction_raw\tSample{s+1}\t{ranked_raw[0][0]}\n")
        out.write(f"scores_conditional\tSample{s+1}\t" + ",".join(f"{p}:{v:.3f}" for p, v in ranked_cond) + "\n")
        out.write(f"scores_raw\tSample{s+1}\t" + ",".join(f"{p}:{v:.3f}" for p, v in ranked_raw) + "\n")
    out.write("final_conditional\tlabels\t" + ",".join(sorted(cond_ll[s].items(), key=lambda kv: kv[1], reverse=True)[0][0] for s in range(4)) + "\n")
    out.write("final_raw\tlabels\t" + ",".join(sorted(raw_ll[s].items(), key=lambda kv: kv[1], reverse=True)[0][0] for s in range(4)) + "\n")

