/workspace/galaxy_gnomad_parser_debug.py.content:
#!/usr/bin/env python3
import gzip
import subprocess
import sys

vcf_path, out_path = sys.argv[1], sys.argv[2]
url = "https://gnomad-public-us-east-1.s3.amazonaws.com/release/2.1.1/vcf/genomes/gnomad.genomes.r2.1.1.sites.1.vcf.bgz"

def open_text(path):
    with open(path, "rb") as probe:
        gz = probe.read(2) == b"\x1f\x8b"
    return gzip.open(path, "rt", encoding="utf-8", errors="replace") if gz else open(path, "rt", encoding="utf-8", errors="replace")

query = {}
with open_text(vcf_path) as handle, open("regions.tsv", "w", encoding="utf-8") as regions:
    for line in handle:
        if line.startswith("#"):
            continue
        f = line.rstrip("\n").split("\t")
        if len(f) < 5:
            continue
        if f[0] == "1" and len(f[3]) == 1 and all(len(a) == 1 for a in f[4].split(",")):
            pos = int(f[1])
            query[pos] = (f[3], f[4])
            regions.write(f"1\t{pos}\t{pos}\n")
            if len(query) >= 100:
                break

proc = subprocess.run(["bcftools", "view", "-R", "regions.tsv", "-H", url], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
lines = proc.stdout.decode("utf-8", "replace").splitlines()
keys = ["AF_afr", "AF_asj", "AF_nfe", "AF_eas", "AF_sas"]
with open(out_path, "w", encoding="utf-8") as out:
    out.write("status\treturn_code\tstderr\n")
    out.write(f"bcftools\t{proc.returncode}\t{proc.stderr.decode('utf-8','replace').replace(chr(10),' ')[:500]}\n")
    out.write("pos\tq_ref\tq_alt\tg_ref\tg_alt\tfield_count\taf_fields\n")
    n = 0
    for line in lines:
        f = line.split("\t")
        if len(f) < 8:
            continue
        try:
            pos = int(f[1])
        except ValueError:
            continue
        if pos not in query:
            continue
        info = {}
        for item in f[7].split(";"):
            if "=" in item:
                k, v = item.split("=", 1)
                info[k] = v
        vals = ",".join(k + "=" + info.get(k, "NA") for k in keys)
        out.write(f"{pos}\t{query[pos][0]}\t{query[pos][1]}\t{f[3]}\t{f[4]}\t{len(f)}\t{vals}\n")
        n += 1
        if n >= 20:
            break

