#!/usr/bin/env python3
import gzip
import math
import subprocess
import sys
import urllib.request

vcf_path, out_path = sys.argv[1], sys.argv[2]
ref_url = "https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/release/20130502/ALL.chr1.phase3_shapeit2_mvncall_integrated_v5b.20130502.genotypes.vcf.gz"
panel_url = "https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/release/20130502/integrated_call_samples_v3.20130502.ALL.panel"
target_pops = {"AFR", "EUR", "EAS", "SAS"}

def open_text(path):
    with open(path, "rb") as probe:
        gz = probe.read(2) == b"\x1f\x8b"
    return gzip.open(path, "rt", encoding="utf-8", errors="replace") if gz else open(path, "rt", encoding="utf-8", errors="replace")

panel = {}
with urllib.request.urlopen(panel_url, timeout=60) as response:
    for raw in response.read().decode("utf-8").splitlines()[1:]:
        if not raw.strip():
            continue
        sample, _pop, super_pop, *_ = raw.split("\t")
        if super_pop in target_pops:
            panel[sample] = super_pop

header = subprocess.check_output(["bcftools", "view", "-h", ref_url])
ref_samples = []
for line in header.decode("utf-8", "replace").splitlines():
    if line.startswith("#CHROM"):
        ref_samples = line.rstrip("\n").split("\t")[9:]
        break
pop_indices = {pop: [] for pop in target_pops}
for i, sample in enumerate(ref_samples):
    pop = panel.get(sample)
    if pop in pop_indices:
        pop_indices[pop].append(i)

query = {}
samples = []
with open_text(vcf_path) as handle, open("regions.tsv", "w", encoding="utf-8") as regions:
    for line in handle:
        if line.startswith("#CHROM"):
            samples = line.rstrip("\n").split("\t")[9:]
            continue
        if line.startswith("#"):
            continue
        f = line.rstrip("\n").split("\t")
        if len(f) < 13:
            continue
        chrom, pos_s, _id, ref, alt = f[:5]
        alts = alt.split(",")
        if chrom != "1" or len(ref) != 1 or not all(len(a) == 1 for a in alts):
            continue
        pos = int(pos_s)
        if pos in query:
            continue
        acs = []
        ok = True
        for sf in f[9:13]:
            gt = sf.split(":", 1)[0].replace("|", "/")
            alleles = gt.split("/")
            if len(alleles) != 2 or "." in alleles:
                ok = False
                break
            acs.append(sum(1 for a in alleles if a != "0"))
        if ok:
            query[pos] = {"ref": ref, "alts": alts, "alt_counts": acs}
            regions.write(f"1\t{pos}\t{pos}\n")

raw_ll = [{pop: 0.0 for pop in target_pops} for _ in range(4)]
cond_ll = [{pop: 0.0 for pop in target_pops} for _ in range(4)]
used = [0, 0, 0, 0]
position_records = 0
exact_records = 0
cmd = ["bcftools", "view", "-R", "regions.tsv", "-H", ref_url]
proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
assert proc.stdout is not None
for raw_line in proc.stdout:
    line = raw_line.decode("utf-8", "replace").rstrip("\n")
    f = line.split("\t")
    if len(f) < 10:
        continue
    try:
        pos = int(f[1])
    except ValueError:
        continue
    if pos not in query:
        continue
    position_records += 1
    q = query[pos]
    if f[3] != q["ref"]:
        continue
    ref_alts = f[4].split(",")
    alt_index = None
    for i, alt in enumerate(ref_alts, start=1):
        if alt in q["alts"]:
            alt_index = i
            break
    if alt_index is None:
        continue
    exact_records += 1
    sample_fields = f[9:]
    pop_freq = {}
    for pop, indices in pop_indices.items():
        allele_count = 0
        allele_total = 0
        for idx in indices:
            gt = sample_fields[idx].split(":", 1)[0].replace("|", "/")
            alleles = gt.split("/")
            for allele in alleles:
                if allele == ".":
                    continue
                allele_total += 1
                if allele.isdigit() and int(allele) == alt_index:
                    allele_count += 1
        if allele_total:
            pop_freq[pop] = min(0.999, max(0.001, allele_count / allele_total))
    if len(pop_freq) != len(target_pops):
        continue
    for s, ac in enumerate(q["alt_counts"]):
        if ac == 0:
            continue
        used[s] += 1
        for pop, p in pop_freq.items():
            p0 = (1 - p) * (1 - p)
            p1 = 2 * p * (1 - p)
            p2 = p * p
            gp = p1 if ac == 1 else p2
            raw_ll[s][pop] += math.log(max(gp, 1e-12))
            cond_ll[s][pop] += math.log(max(gp / max(1 - p0, 1e-12), 1e-12))

stderr = proc.stderr.read() if proc.stderr is not None else b""
code = proc.wait()

with open(out_path, "w", encoding="utf-8") as out:
    out.write("section\tkey\tvalue\n")
    out.write(f"summary\tquery_snvs\t{len(query)}\n")
    out.write(f"summary\tref_sample_counts\t" + ",".join(f"{p}:{len(v)}" for p, v in sorted(pop_indices.items())) + "\n")
    out.write(f"summary\tposition_records\t{position_records}\n")
    out.write(f"summary\texact_records\t{exact_records}\n")
    out.write("summary\tused_by_sample\t" + ",".join(map(str, used)) + "\n")
    for s in range(4):
        ranked_cond = sorted(cond_ll[s].items(), key=lambda kv: kv[1], reverse=True)
        ranked_raw = sorted(raw_ll[s].items(), key=lambda kv: kv[1], reverse=True)
        out.write(f"prediction_conditional\tSample{s+1}\t{ranked_cond[0][0]}\n")
        out.write(f"scores_conditional\tSample{s+1}\t" + ",".join(f"{p}:{v:.3f}" for p, v in ranked_cond) + "\n")
        out.write(f"prediction_raw\tSample{s+1}\t{ranked_raw[0][0]}\n")
        out.write(f"scores_raw\tSample{s+1}\t" + ",".join(f"{p}:{v:.3f}" for p, v in ranked_raw) + "\n")
    out.write("final_conditional\tlabels\t" + ",".join(sorted(cond_ll[s].items(), key=lambda kv: kv[1], reverse=True)[0][0] for s in range(4)) + "\n")
    out.write("final_raw\tlabels\t" + ",".join(sorted(raw_ll[s].items(), key=lambda kv: kv[1], reverse=True)[0][0] for s in range(4)) + "\n")
    out.write(f"bcftools\treturn_code\t{code}\n")
    if stderr:
        out.write("bcftools\tstderr\t" + stderr.decode("utf-8", "replace").replace("\n", " ")[:1000] + "\n")

